"""Apply the factual legal-QA upgrade to an existing v4 project; standard library only.
Usage: python apply_factual_upgrade.py --root PATH --check
       python apply_factual_upgrade.py --root PATH
Preserves databases/credentials/uploads. Refuses conflicting local code. Backups and rollback included.
"""
import argparse,base64,hashlib,json,os,shutil,sys,tempfile,zlib
from datetime import datetime,timezone
from pathlib import Path
PAYLOAD = ''
PAYLOAD_SHA256 = '41f283f81700156a79e98df02fac3bf2b76ffba2cb507bf49373fde2be90609e'

def sha(data):return hashlib.sha256(data).hexdigest()

def atomic_write(path,data):
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,name=tempfile.mkstemp(prefix=path.name+'.',suffix='.tmp',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
        os.replace(name,path)
    finally:
        if os.path.exists(name):os.unlink(name)

def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--root',type=Path,required=True);p.add_argument('--check',action='store_true');args=p.parse_args()
    root=args.root.resolve()
    if not (root/'backend/app').is_dir() or not (root/'frontend/src').is_dir():
        raise ValueError('Choose the project root containing backend/app and frontend/src.')
    data=zlib.decompress(base64.b64decode(PAYLOAD))
    if sha(data)!=PAYLOAD_SHA256:raise ValueError('Upgrade payload checksum failed. Download the file again.')
    bundle=json.loads(data);plan=[];conflicts=[]
    for f in bundle['files']:
        rel=Path(f['path']);target=(root/rel).resolve()
        if rel.is_absolute() or '..' in rel.parts or root not in target.parents:raise ValueError('Unsafe package path.')
        content=base64.b64decode(f['content'])
        if sha(content)!=f['new_sha256']:raise ValueError('File checksum mismatch: '+str(rel))
        previous=target.read_bytes() if target.exists() else None
        current=sha(previous) if previous is not None else None
        if current==f['new_sha256']:
            print('Already updated:',rel);continue
        if current!=f['old_sha256']:
            conflicts.append(str(rel));continue
        plan.append((target,rel,content,previous))
    if conflicts:
        print('No files changed. These files differ from the v4 baseline:')
        for name in conflicts:print('  CONFLICT:',name)
        print('Keep your files. Share this list/current source for a merge; do not reset your databases.')
        return 2
    print(f'Validated {len(bundle["files"])} files; {len(plan)} need updating.')
    if args.check:return 0
    if not plan:
        print('All update files are already present.');return 0
    backup_root=root/'upgrade_backups';backup_root.mkdir(exist_ok=True)
    backup=Path(tempfile.mkdtemp(prefix='factual_v5_'+datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')+'_',dir=backup_root))
    # Complete all backups before changing any source file.
    for target,rel,content,previous in plan:
        if previous is not None:
            dest=backup/rel;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(previous)
    (backup/'backup_manifest.json').write_text(json.dumps({'version':bundle['version'],'changed':[{'path':str(rel),'existed':previous is not None} for _,rel,_,previous in plan]},indent=2),encoding='utf-8')
    applied=[]
    try:
        for target,rel,content,previous in plan:
            # Refuse changes made by an editor after preflight/backups.
            current=target.read_bytes() if target.exists() else None
            if current!=previous:raise ValueError('Source changed during installation: '+str(rel))
            atomic_write(target,content);applied.append((target,previous));print('Updated:',rel)
    except Exception:
        rollback_errors=[]
        for target,previous in reversed(applied):
            try:
                if previous is None:target.unlink(missing_ok=True)
                else:atomic_write(target,previous)
            except OSError:rollback_errors.append(str(target))
        if rollback_errors:print('Rollback needs manual recovery from backup:',rollback_errors)
        print('Backup:',backup)
        raise
    print('Upgrade applied. Backup:',backup)
    print('Next: follow docs/FACTUAL_SETUP_AND_WORKFLOW.md; run dependency installs, restart services, then test ONE question group.')
    return 0

if __name__=='__main__':
    try:raise SystemExit(main())
    except Exception as exc:print('ERROR:',str(exc),file=sys.stderr);raise SystemExit(2)
